import numpy as np

def calculate_perimeter(N):
    """
    Calculates the perimeter of a filled diamond shape of radius N 
    (Manhattan distance ball of radius N).
    F_N = {(x, y) | |x| + |y| <= N}
    Perimeter is the number of edges between F_N and its complement.
    """
    if N < 0:
        return 0

    # Define the set of flooded cells F_N
    F_N = set()
    for x in range(-N, N + 1):
        for y in range(-N, N + 1):
            if abs(x) + abs(y) <= N:
                F_N.add((x, y))

    perimeter = 0
    # Check neighbors (up, down, left, right)
    for x, y in F_N:
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in F_N:
                perimeter += 1

    return perimeter

# Test values for N (number of turns elapsed)
N_values = [0, 1, 2, 3, 4, 5, 10]
results = {}
for N in N_values:
    P = calculate_perimeter(N)
    results[N] = P
    print(f"N={N}, Perimeter P={P}")

# Check the growth rate P(N)/N
rates = {}
for N, P in results.items():
    if N > 0:
        rates[N] = P / N
        print(f"N={N}, Rate P/N = {rates[N]:.2f}")

